const hamburger = document.getElementById('hamburger');
    const mobileNav = document.getElementById('mobileNav');
    hamburger.addEventListener('click', () => {
      hamburger.classList.toggle('active');
      mobileNav.classList.toggle('active');
      document.body.style.overflow = mobileNav.classList.contains('active') ? 'hidden' : '';
    });
    function closeMobileNav() {
      hamburger.classList.remove('active');
      mobileNav.classList.remove('active');
      document.body.style.overflow = '';
    }
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 60);
    });
    const revealElements = document.querySelectorAll('.reveal');
    const revealObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
    revealElements.forEach(el => revealObserver.observe(el));
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];
    const checkinInput = document.getElementById('checkin');
    const checkoutInput = document.getElementById('checkout');
    checkinInput.min = todayStr;
    checkinInput.value = todayStr;
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowStr = tomorrow.toISOString().split('T')[0];
    checkoutInput.min = tomorrowStr;
    checkoutInput.value = tomorrowStr;
    checkinInput.addEventListener('change', () => {
      const ci = new Date(checkinInput.value);
      const nextDay = new Date(ci);
      nextDay.setDate(nextDay.getDate() + 1);
      checkoutInput.min = nextDay.toISOString().split('T')[0];
      if (new Date(checkoutInput.value) <= ci) {
        checkoutInput.value = nextDay.toISOString().split('T')[0];
      }
    });
    const bookingForm = document.getElementById('bookingForm');
    const bookingConfirmation = document.getElementById('bookingConfirmation');
    function showError(inputId, errorId) {
      document.getElementById(inputId).classList.add('error');
      document.getElementById(errorId).classList.add('visible');
    }
    function clearErrors() {
      document.querySelectorAll('.error').forEach(el => el.classList.remove('error'));
      document.querySelectorAll('.error-msg').forEach(el => el.classList.remove('visible'));
    }
    bookingForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();
      let valid = true;
      const checkin = checkinInput.value;
      const checkout = checkoutInput.value;
      const roomType = document.getElementById('roomType').value;
      const guests = document.getElementById('guests').value;
      const name = document.getElementById('guestName').value.trim();
      const phone = document.getElementById('guestPhone').value.trim();
      const email = document.getElementById('guestEmail').value.trim();
      if (!checkin) { showError('checkin', 'checkinError'); valid = false; }
      if (!checkout || new Date(checkout) <= new Date(checkin)) {
        showError('checkout', 'checkoutError'); valid = false;
      }
      if (!roomType) { showError('roomType', 'roomTypeError'); valid = false; }
      if (!guests) { showError('guests', 'guestsError'); valid = false; }
      if (!name) { showError('guestName', 'guestNameError'); valid = false; }
      if (!phone || phone.length < 7) { showError('guestPhone', 'guestPhoneError'); valid = false; }
      if (!email || !email.includes('@') || !email.includes('.')) {
        showError('guestEmail', 'guestEmailError'); valid = false;
      }
      if (!valid) return;
      const refNum = 'TS-' + Math.floor(100000 + Math.random() * 900000);
      document.getElementById('confirmationRef').textContent = 'REF: ' + refNum;
      let typeId = 'deluxe';
      if (roomType.includes('Garden')) typeId = 'garden';
      else if (roomType.includes('Suite')) typeId = 'suite';
      else if (roomType.includes('Executive')) typeId = 'executive';
      fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          guest_name: name,
          guest_phone: phone,
          guest_email: email,
          room_type_id: typeId,
          guests_count: parseInt(guests) || 2,
          checkin_date: checkin,
          checkout_date: checkout,
          source: 'website'
        })
      })
      .then(r => r.json())
      .then(res => {
        if (res.success && res.ref_number) {
          document.getElementById('confirmationRef').textContent = 'REF: ' + res.ref_number + (res.assigned_room ? ' • Room ' + res.assigned_room : '');
        }
      })
      .catch(err => console.log('Booking sync offline/local mode'));
      const nights = Math.round((new Date(checkout) - new Date(checkin)) / (1000 * 60 * 60 * 24));
      const fmtDate = (d) => new Date(d).toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
      const detailsEl = document.getElementById('confirmationDetails');
      detailsEl.innerHTML = `
        <div class="detail-row"><span class="detail-label">Guest Name</span><span class="detail-value">${name}</span></div>
        <div class="detail-row"><span class="detail-label">Phone</span><span class="detail-value">${phone}</span></div>
        <div class="detail-row"><span class="detail-label">Email</span><span class="detail-value">${email}</span></div>
        <div class="detail-row"><span class="detail-label">Room</span><span class="detail-value">${roomType.split('—')[0].trim()}</span></div>
        <div class="detail-row"><span class="detail-label">Guests</span><span class="detail-value">${guests}</span></div>
        <div class="detail-row"><span class="detail-label">Check-in</span><span class="detail-value">${fmtDate(checkin)}</span></div>
        <div class="detail-row"><span class="detail-label">Check-out</span><span class="detail-value">${fmtDate(checkout)}</span></div>
        <div class="detail-row"><span class="detail-label">Duration</span><span class="detail-value">${nights} night${nights > 1 ? 's' : ''}</span></div>
      `;
      if (roomType.includes('Heritage Deluxe')) {
        if (roomInventory.room1 > 0) roomInventory.room1--;
      } else if (roomType.includes('Premium Garden')) {
        if (roomInventory.room2 > 0) roomInventory.room2--;
      } else if (roomType.includes('Grand Suite')) {
        if (roomInventory.room3 > 0) roomInventory.room3--;
      } else if (roomType.includes('Executive')) {
        if (roomInventory.room4 > 0) roomInventory.room4--;
      }
      updateRoomInventoryUI();
      bookingForm.style.display = 'none';
      bookingConfirmation.classList.add('active');
      bookingConfirmation.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
    function resetBooking() {
      bookingForm.reset();
      clearErrors();
      checkinInput.value = todayStr;
      checkoutInput.value = tomorrowStr;
      checkoutInput.min = tomorrowStr;
      bookingConfirmation.classList.remove('active');
      bookingForm.style.display = '';
    }
    const lightbox = document.getElementById('lightbox');
    const lightboxImg = document.getElementById('lightboxImg');
    function openLightbox(el) {
      const img = el.querySelector('img');
      lightboxImg.src = img.src;
      lightboxImg.alt = img.alt;
      lightbox.classList.add('active');
      document.body.style.overflow = 'hidden';
    }
    function closeLightbox() {
      lightbox.classList.remove('active');
      document.body.style.overflow = '';
    }
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeLightbox();
    });
    lightboxImg.addEventListener('click', (e) => e.stopPropagation());
    function handleContactSubmit(e) {
      e.preventDefault();
      const btn = document.getElementById('contactSubmitBtn');
      btn.textContent = 'Message Sent ✓';
      btn.style.background = 'linear-gradient(135deg, var(--green-mid), var(--green-dark))';
      btn.style.color = 'var(--white)';
      btn.disabled = true;
      setTimeout(() => {
        btn.textContent = 'Send Message';
        btn.style.background = '';
        btn.style.color = '';
        btn.disabled = false;
        document.getElementById('contactForm').reset();
      }, 3000);
    }
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          const offset = 70;
          const position = target.getBoundingClientRect().top + window.pageYOffset - offset;
          window.scrollTo({ top: position, behavior: 'smooth' });
        }
      });
    });
    const TOTAL_ROOMS = 24;
    const roomInventory = {
      room1: 3, // Heritage Deluxe
      room2: 2, // Premium Garden View
      room3: 1, // Grand Suite
      room4: 1  // Executive Room
    };
    function updateRoomInventoryUI() {
      const avail = roomInventory.room1 + roomInventory.room2 + roomInventory.room3 + roomInventory.room4;
      const occupied = TOTAL_ROOMS - avail;
      const occPct = Math.round((occupied / TOTAL_ROOMS) * 100);
      const heroRoom = document.getElementById('heroRoomStat');
      if (heroRoom) heroRoom.textContent = `${avail} Rooms Available`;
      const availEl = document.getElementById('availCount');
      const occEl = document.getElementById('occCount');
      if (availEl) availEl.textContent = avail;
      if (occEl) occEl.textContent = `${occupied} Occupied (${occPct}%)`;
      const s1 = document.getElementById('stockRoom1');
      if (s1) {
        s1.className = 'room-stock-tag ' + (roomInventory.room1 <= 1 ? 'critical' : roomInventory.room1 <= 2 ? 'low' : 'avail');
        s1.innerHTML = (roomInventory.room1 <= 1 ? '🔴 ' : roomInventory.room1 <= 2 ? '🟡 ' : '🟢 ') +
          `<span id="stockCount1">${roomInventory.room1}</span> ` +
          (roomInventory.room1 === 0 ? 'Sold Out Today' : roomInventory.room1 === 1 ? 'Only 1 Left' : 'Available');
      }
      const s2 = document.getElementById('stockRoom2');
      if (s2) {
        s2.className = 'room-stock-tag ' + (roomInventory.room2 <= 1 ? 'critical' : roomInventory.room2 <= 2 ? 'low' : 'avail');
        s2.innerHTML = (roomInventory.room2 <= 1 ? '🔴 ' : roomInventory.room2 <= 2 ? '🟡 ' : '🟢 ') +
          `<span id="stockCount2">${roomInventory.room2}</span> ` +
          (roomInventory.room2 === 0 ? 'Sold Out' : roomInventory.room2 === 1 ? 'Only 1 Left' : 'Left Today');
      }
      const s3 = document.getElementById('stockRoom3');
      if (s3) {
        s3.className = 'room-stock-tag ' + (roomInventory.room3 <= 1 ? 'critical' : 'avail');
        s3.innerHTML = (roomInventory.room3 <= 1 ? '🔴 ' : '🟢 ') +
          `<span id="stockCount3">${roomInventory.room3}</span> ` +
          (roomInventory.room3 === 0 ? 'Sold Out' : 'Left (High Demand)');
      }
      const s4 = document.getElementById('stockRoom4');
      if (s4) {
        s4.className = 'room-stock-tag ' + (roomInventory.room4 <= 1 ? 'critical' : roomInventory.room4 <= 2 ? 'low' : 'avail');
        s4.innerHTML = (roomInventory.room4 <= 1 ? '🔴 ' : roomInventory.room4 <= 2 ? '🟡 ' : '🟢 ') +
          `<span id="stockCount4">${roomInventory.room4}</span> ` +
          (roomInventory.room4 === 0 ? 'Sold Out' : roomInventory.room4 === 1 ? 'Only 1 Left' : 'Available');
      }
    }
    fetch('/api/rooms/summary')
      .then(r => r.json())
      .then(data => {
        if (data.success && data.categories) {
          data.categories.forEach(cat => {
            if (cat.room_type_id === 'deluxe') roomInventory.room1 = cat.available_count;
            if (cat.room_type_id === 'garden') roomInventory.room2 = cat.available_count;
            if (cat.room_type_id === 'suite') roomInventory.room3 = cat.available_count;
            if (cat.room_type_id === 'executive') roomInventory.room4 = cat.available_count;
          });
          updateRoomInventoryUI();
        }
      })
      .catch(() => {});
    const tablesData = [
      { id: 1, name: "Table 1", cap: "2-Seater (Window)", occ: true },
      { id: 2, name: "Table 2", cap: "4-Seater (Hall)", occ: false },
      { id: 3, name: "Table 3", cap: "4-Seater (Hall)", occ: true },
      { id: 4, name: "Table 4", cap: "6-Seater (Booth)", occ: false },
      { id: 5, name: "Table 5", cap: "2-Seater (Garden)", occ: true },
      { id: 6, name: "Table 6", cap: "4-Seater (Garden)", occ: true },
      { id: 7, name: "Table 7", cap: "4-Seater (Courtyard)", occ: true, qr: true },
      { id: 8, name: "Table 8", cap: "2-Seater (Courtyard)", occ: true },
      { id: 9, name: "Table 9", cap: "8-Seater (Family)", occ: false },
      { id: 10, name: "Table 10", cap: "4-Seater (Hall)", occ: true },
      { id: 11, name: "Table 11", cap: "4-Seater (Garden)", occ: true },
      { id: 12, name: "Table 12", cap: "2-Seater (Window)", occ: false },
      { id: 13, name: "Table 13", cap: "6-Seater (Booth)", occ: true },
      { id: 14, name: "Table 14", cap: "4-Seater (Terrace)", occ: false }
    ];
    function renderTables() {
      const grid = document.getElementById('floorGrid');
      if (!grid) return;
      grid.innerHTML = '';
      let occCount = 0;
      tablesData.forEach(t => {
        if (t.occ) occCount++;
        const card = document.createElement('div');
        card.className = `table-card ${t.occ ? 'occupied' : 'available'} ${t.qr ? 'active-qr' : ''}`;
        card.onclick = () => toggleTable(t.id);
        card.title = 'Click to toggle status (Occupied / Available)';
        card.innerHTML = `
          ${t.qr ? '<span class="table-qr-badge">QR DEMO</span>' : ''}
          <div class="table-number">${t.name}</div>
          <div class="table-capacity">${t.cap}</div>
          <span class="table-status-pill ${t.occ ? 'occ' : 'free'}">${t.occ ? 'Occupied' : 'Available'}</span>
        `;
        grid.appendChild(card);
      });
      const freeCount = tablesData.length - occCount;
      const occEl = document.getElementById('tablesOccCount');
      const freeEl = document.getElementById('tablesAvailCount');
      const waitEl = document.getElementById('tablesWaitTime');
      const heroTable = document.getElementById('heroTableStat');
      if (occEl) occEl.textContent = occCount;
      if (freeEl) freeEl.textContent = freeCount;
      if (waitEl) waitEl.textContent = freeCount > 2 ? '< 5 mins' : freeCount > 0 ? '10-15 mins' : '25-30 mins';
      if (heroTable) heroTable.textContent = `${occCount} / ${tablesData.length} Tables Occupied (${freeCount} Free)`;
    }
    function toggleTable(id) {
      const table = tablesData.find(t => t.id === id);
      if (table) {
        table.occ = !table.occ;
        renderTables();
      }
    }
    function toggleRandomTable() {
      const randomIndex = Math.floor(Math.random() * tablesData.length);
      tablesData[randomIndex].occ = !tablesData[randomIndex].occ;
      renderTables();
    }
    const PRODUCTION_URL = 'https://www.tapstay.in/';
    let currentQrMode = (window.location.hostname === 'www.tapstay.in' || window.location.hostname === 'tapstay.in') ? 'current' : 'public';
    const LAN_IP = '172.16.71.216';
    const PORT = window.location.port || '8080';
    function getBaseUrl() {
      if (currentQrMode === 'public') {
        return PRODUCTION_URL;
      } else if (currentQrMode === 'lan') {
        return 'http://' + LAN_IP + (PORT ? ':' + PORT : '') + '/';
      } else if (currentQrMode === 'local') {
        return 'http://localhost' + (PORT ? ':' + PORT : '') + '/';
      } else {
        const path = window.location.pathname;
        const dir = path.substring(0, path.lastIndexOf('/') + 1);
        return window.location.origin + (dir || '/');
      }
    }
    function renderQRCodes() {
      if (typeof QRCode === 'undefined') {
        setTimeout(renderQRCodes, 100);
        return;
      }
      const base = getBaseUrl();
      const conciergeUrl = base + 'concierge.html?room=204&type=Heritage+Deluxe+Room';
      const diningUrl = base + 'order.html?table=7';
      const whatsappUrl = 'https://wa.me/919876543210?text=Hello%20HOTEL%20Dehradun%2C%20I%20would%20like%20to%20enquire%20about%20room%20availability%20and%20amenities.';
      const reviewUrl = base + 'review.html?stay=recent';
      const btnC = document.getElementById('btnConciergeLink');
      const btnD = document.getElementById('btnDiningLink');
      const btnR = document.getElementById('btnReviewLink');
      if (btnC) btnC.href = conciergeUrl;
      if (btnD) btnD.href = diningUrl;
      if (btnR) btnR.href = reviewUrl;
      ['qrConcierge', 'qrDining', 'qrWhatsapp', 'qrReview'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = '';
      });
      const qrConfig = {
        width: 150,
        height: 150,
        colorDark: '#1B4332',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.M
      };
      try {
        new QRCode(document.getElementById('qrConcierge'), { ...qrConfig, text: conciergeUrl });
        new QRCode(document.getElementById('qrDining'), { ...qrConfig, text: diningUrl });
        new QRCode(document.getElementById('qrWhatsapp'), { ...qrConfig, text: whatsappUrl });
        new QRCode(document.getElementById('qrReview'), { ...qrConfig, text: reviewUrl });
        setTimeout(() => {
          ['qrConcierge', 'qrDining', 'qrWhatsapp', 'qrReview'].forEach(id => {
            const el = document.getElementById(id);
            if (el) {
              const canvases = el.querySelectorAll('canvas');
              canvases.forEach(c => c.remove());
            }
          });
        }, 50);
      } catch (err) {
        console.error('Error generating QR codes:', err);
      }
      const hint = document.getElementById('qrTargetHint');
      if (hint) {
        if (currentQrMode === 'public' || currentQrMode === 'current') {
          hint.innerHTML = 'Encoding live secure URL: <strong style="color:var(--green-dark);">' + base + '</strong> (Scannable from ANY smartphone & mobile network)';
        } else if (currentQrMode === 'lan') {
          hint.innerHTML = 'Encoding local Wi-Fi URL: <strong style="color:var(--green-dark);">' + base + '</strong> (Phones on same Wi-Fi)';
        } else {
          hint.innerHTML = 'Encoding local URL: <strong style="color:var(--green-dark);">' + base + '</strong> (For browser testing on this laptop)';
        }
      }
    }
    function switchQrHost(mode) {
      currentQrMode = mode;
      const btnPublic = document.getElementById('btnTunnel');
      const btnLan = document.getElementById('btnLanIp');
      const btnLocal = document.getElementById('btnLocalhost');
      if (btnPublic) btnPublic.classList.toggle('active', mode === 'public' || mode === 'current');
      if (btnLan) btnLan.classList.toggle('active', mode === 'lan');
      if (btnLocal) btnLocal.classList.toggle('active', mode === 'local');
      renderQRCodes();
    }
    function initOccupancy() {
      updateRoomInventoryUI();
      renderTables();
      renderQRCodes();
    }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initOccupancy);
    } else {
      setTimeout(initOccupancy, 50);
    }